let collectionMeta=null,tableColumns=['name','maker','scale','usage','location','availability'],columnDraft=[],choiceCatalogue=null,choiceField='maker',choiceQuery='',choiceDraft=null,bulkDraft=null;
function choiceSuggestions(name,values){const key=name.replace(/^(technical|factory)\./,'tech_').replace(/^custom\./,'custom_').replace(/^(value|labels)_/,'');const all=[...values];if(collectionMeta?.choices.some(f=>f.key===key)){all.push(...(db.choices[key]||[]));if(key==='track')all.push(...db.setups.map(s=>s.track),...db.tests.map(t=>t.track));if(key==='driver')all.push(...db.tests.map(t=>t.driver));}return [...new Set(all.filter(v=>typeof v==='string'&&v.trim()).map(value=>db?.choiceAliases?.find(a=>a.field===key&&a.from===value)?.to||value))];}
function columnLabel(key){if(key.startsWith('tech_'))return techLabels[key.slice(5)]||key.slice(5);if(key.startsWith('custom_'))return db.customFields.find(f=>f.id===key.slice(7))?.label||'Custom field';return fieldLabel(key);}
function columnValue(c,key){if(key.startsWith('tech_'))return c.technical?.[key.slice(5)]||'';if(key.startsWith('custom_'))return c.custom?.[key.slice(7)]||'';return c[key]??'';}
function renderCollectionTable(list,check){const columns=local()?tableColumns:['name','maker','scale','usage','raceClass'];return `<div class="table-wrap"><table><thead><tr><th></th>${columns.map(k=>`<th>${esc(columnLabel(k))}</th>`).join('')}</tr></thead><tbody>${list.map(c=>`<tr><td>${check(c)}</td>${columns.map(k=>{const v=columnValue(c,k);return `<td>${k==='name'?`<button type="button" class="table-name collection-name" data-action="open-car" data-id="${c.id}">${c.picture&&!columns.includes('picture')?`<img class="table-thumb" src="${esc(thumbnailSource(c.picture))}" alt="" loading="lazy" decoding="async">`:''}<span>${esc(c.name)}<small>${esc(c.number||c.maker)}</small></span></button>`:k==='picture'?(c.picture?`<img class="table-thumb" src="${esc(thumbnailSource(c.picture))}" alt="${esc(c.name)}" loading="lazy" decoding="async">`:'—'):Array.isArray(v)?v.map(x=>badge(x,k==='usage'?'usage':'')).join(' '):esc(v||'—')}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
function columnEditorBody(){return `<p class="muted">Choose up to 16 columns. Name remains available so you can open a car. Saved views remember their own column order.</p><div id="column-order">${columnDraft.map((key,index)=>`<div class="list-row"><strong>${esc(columnLabel(key))}</strong><div class="actions">${index?btn('↑','column-up','small',String(index)):''}${index<columnDraft.length-1?btn('↓','column-down','small',String(index)):''}${key!=='name'?btn('Remove','column-remove','small',String(index)):''}</div></div>`).join('')}</div><div class="row mt"><label class="field">Add a column<select id="column-add-select">${collectionMeta.columns.filter(c=>!columnDraft.includes(c.key)).map(c=>`<option value="${c.key}">${esc(c.group+' · '+columnLabel(c.key))}</option>`).join('')}</select></label>${btn('Add column','column-add')}</div>`;}
function configureColumns(){columnDraft=[...tableColumns];const revision=db.revision;modal('Table columns',`<div id="columns-editor">${columnEditorBody()}</div>`,async()=>{await change('columns.save',{revision,columns:columnDraft});tableColumns=[...columnDraft];mode='table';},'Save column order');}
function refreshColumnEditor(){$('#columns-editor').innerHTML=columnEditorBody();}
async function loadChoices(){choiceCatalogue=await api('plan','choices.catalogue');collectionMeta=choiceCatalogue;if(!choiceCatalogue.choices.some(f=>f.key===choiceField))choiceField=choiceCatalogue.choices[0].key;}
function renderChoiceRows(){const rows=(choiceCatalogue.values[choiceField]||[]).filter(row=>[row.value,...row.aliases].join(' ').toLowerCase().includes(choiceQuery.toLowerCase()));return rows.length?`<div class="table-wrap"><table><thead><tr><th>Reusable value</th><th>Current car records</th><th></th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.value)}</strong>${row.aliases.length?`<div class="tiny muted">Previous spellings: ${row.aliases.map(esc).join(', ')}</div>`:''}</td><td>${row.cars}</td><td>${btn('Rename / merge…','rename-choice','small',row.value)}</td></tr>`).join('')}</tbody></table></div>`:empty('No saved values in this field','Values appear as you enter cars. You can also add an option now.',btn('Add option','add-choice','primary'));}
function renderLibrary(){if(libraryTab==='parts')return renderCatalogueManager();if(!local())return empty('Your choice library is local','Switch to your own database to organise reusable values.');if(!choiceCatalogue)return libraryTabs()+empty('Reusable choices','Load the values from your collection.',btn('Load library','reload-choices','primary'));return heading('Library','Correct spellings and merge duplicates while preserving historical snapshots.',btn('Add option','add-choice','primary')+btn('Refresh','reload-choices'))+libraryTabs()+`<div class="library-layout">${libraryRail()}<div class="library-content"><div class="toolbar"><label class="field">Field<select id="library-field">${choiceCatalogue.choices.map(f=>`<option value="${f.key}" ${f.key===choiceField?'selected':''}>${esc(f.group+' · '+(f.key.startsWith('tech_')?columnLabel(f.key):f.label))}</option>`).join('')}</select></label><label class="search">${icon('search')}<input id="choice-search" placeholder="Find a value or previous spelling…" value="${esc(choiceQuery)}" aria-label="Find reusable choices"></label></div><div class="note info">Renames update suggestions. You can also correct matching current car values after reviewing the changes. Saved setups, test records, factory references and previous history stay unchanged. Inventory component names are managed in Parts.</div><div id="choice-results">${renderChoiceRows()}</div></div></div>`;}
function addChoice(){const revision=choiceCatalogue.revision,fieldKey=choiceField;simpleForm('Add reusable option',field('value','New value',''),async values=>{await change('choice.add',{revision,field:fieldKey,value:values.value});await loadChoices();});}
function renameChoice(value){choiceDraft={field:choiceField,from:value,revision:choiceCatalogue.revision};modal('Rename or merge a choice',`<p>Current value: <strong>${esc(value)}</strong></p>${field('to','New or existing value','','text',(choiceCatalogue.values[choiceField]||[]).map(r=>r.value).filter(v=>v!==value))}<label class="check-row"><input name="updateCars" type="checkbox" checked>Also correct matching current car values, including archived cars</label><p class="tiny muted">Tracked component fields are skipped. Track and driver history is preserved. Choosing an existing value merges the suggestions.</p>${btn('Review changes →','preview-choice','primary')}`,null);}
async function previewChoice(){const payload={...choiceDraft,to:$('[name="to"]').value,updateCars:$('[name="updateCars"]').checked};let plan;try{plan=await api('plan','choice.preview',payload);}catch(e){$('#form-error').hidden=false;$('#form-error').textContent=e.message;return;}modal(plan.merging?'Review merge':'Review rename',`<p><strong>${esc(plan.from)}</strong> → <strong>${esc(plan.to)}</strong></p><p>${plan.rows.length} current car record(s) will change. Future suggestions will use the new value.</p>${plan.rows.length?`<div class="table-wrap"><table><thead><tr><th>Car</th><th>Before</th><th>After</th></tr></thead><tbody>${plan.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(Array.isArray(r.before)?r.before.join(', '):r.before)}</td><td>${esc(Array.isArray(r.after)?r.after.join(', '):r.after)}</td></tr>`).join('')}</tbody></table></div>`:''}${plan.skipped.length?`<div class="note mt"><strong>Left unchanged: ${plan.skipped.length} tracked car(s)</strong>${plan.skipped.map(r=>`<p>${esc(r.name)}: ${esc(r.reason)}</p>`).join('')}</div>`:''}<label class="check-row mt"><input name="confirmed" type="checkbox" required>I confirm the reviewed change.</label>`,async values=>{await change('choice.rename',{...payload,confirmed:!!values.confirmed});await loadChoices();toast('Reusable choices updated.');},plan.merging?'Merge choices':'Rename choice');}
function bulkEdit(){bulkDraft={ids:[...selected],revision:db.revision};modal('Edit selected cars',`<p><strong>${bulkDraft.ids.length} cars selected.</strong> Only enabled fields change. An enabled empty field clears that value.</p><div class="form-grid">${collectionMeta.bulkFields.map(k=>`<div><label class="check-row"><input name="use_${k}" type="checkbox">Change ${esc(fieldLabel(k))}</label>${field('value_'+k,fieldLabel(k),'','text',db.cars.map(c=>c[k]).filter(Boolean))}</div>`).join('')}</div><div class="two-col mt">${['usage','tags'].map(k=>panel(fieldLabel(k),field('mode_'+k,'Action','keep','select',['keep','add','remove','replace'])+field('labels_'+k,'Values (comma separated)','','text',db.choices[k]||[]))).join('')}</div><p class="tiny muted">Replace with no labels clears the selected label list. Inventory and technical specifications are managed through the workshop.</p>${btn('Review changes →','preview-bulk','primary')}`,null);}
async function previewBulk(){const values=Object.fromEntries(new FormData($('#modal-form'))),updates={},labels={};for(const k of collectionMeta.bulkFields)if(values['use_'+k])updates[k]=values['value_'+k];for(const k of ['usage','tags'])if(values['mode_'+k]!=='keep')labels[k]={mode:values['mode_'+k],values:comma(values['labels_'+k])};const payload={...bulkDraft,updates,labels};let plan;try{plan=await api('plan','bulk.preview',payload);}catch(e){$('#form-error').hidden=false;$('#form-error').textContent=e.message;return;}modal('Review bulk edit',`<p><strong>${plan.changed} of ${plan.selected} selected cars will change.</strong> These updates will be saved together.</p>${plan.rows.length?`<div class="table-wrap"><table><thead><tr><th>Car</th><th>Field</th><th>Before</th><th>After</th></tr></thead><tbody>${plan.rows.flatMap(r=>r.changes.map(c=>`<tr><td>${esc(r.name)}</td><td>${esc(fieldLabel(c.key))}</td><td>${esc(Array.isArray(c.before)?c.before.join(', '):c.before||'Empty')}</td><td>${esc(Array.isArray(c.after)?c.after.join(', '):c.after||'Empty')}</td></tr>`)).join('')}</tbody></table></div>`:'<p>The selected records already match these changes.</p>'}<label class="check-row mt"><input type="checkbox" name="confirmed" required>I confirm these changes to the selected cars.</label>`,async values=>{await change('car.bulk',{...payload,confirmed:!!values.confirmed});toast('Bulk changes saved.');},'Apply bulk changes');}
function renderDocuments(c){if(!local())return '';const docs=db.documents.filter(d=>d.carId===c.id);return `<div class="page-head mt"><div><h2>Private documents</h2><p>Manuals, receipts, setup sheets and inspection records.</p></div>${btn('Attach document','attach-document','primary',c.id)}</div><div class="note info">Documents are stored inside complete backups. They are excluded from car exports and public browsing. Dealership copies share the complete collection. Up to 20 MB per file. Guides are also available in Workshop → Manuals and Part Guides.</div>${docs.length?`<div class="stack">${docs.map(d=>panel(d.title,`<div class="row">${badge(d.category)}${badge('Private')}<span class="tiny muted">${esc(d.name)} · ${(d.size/1024).toFixed(1)} KB · ${date(d.added)}</span></div><div class="actions mt">${btn('Open copy','open-document','',d.id)}${btn('Export copy','export-document','',d.id)}${btn('Remove…','remove-document','small',d.id)}</div>`)).join('')}</div>`:'<p class="muted">No documents attached yet.</p>'}<p class="tiny muted mt">Open copy uses your default document app. Edits made there are not saved back into this database; export a copy to keep external edits.</p>`;}
async function attachDocument(id){const c=db.cars.find(c=>c.id===id),revision=c.revision;const document=await api('file','document.pick');if(!document)return;modal('Attach private document',`<p>${esc(document.name)} · ${(document.size/1024).toFixed(1)} KB</p><div class="form-grid">${field('title','Document title',document.name.slice(0,200))}${field('category','Category','Document','text',['Manual','Receipt','Setup sheet','Inspection','Document',...db.documents.map(d=>d.category)])}</div>`,async values=>{await change('document.add',{carId:id,revision,document,title:values.title,category:values.category});},'Attach document');}
function removeDocument(id){if(db.documents.find(d=>d.id===id)?.guide){removeGuide(id);return;}const doc=db.documents.find(d=>d.id===id),c=db.cars.find(c=>c.id===doc.carId);modal('Remove document',`<p>Remove <strong>${esc(doc.title)}</strong> from this car? The original file on your computer and earlier complete backups are unchanged.</p>`,async()=>change('document.remove',{id,revision:c.revision}),'Remove attachment');}
document.addEventListener('input',e=>{if(e.target.id==='choice-search'){choiceQuery=e.target.value;$('#choice-results').innerHTML=renderChoiceRows();}});
document.addEventListener('change',e=>{if(e.target.id==='library-field'){choiceField=e.target.value;choiceQuery='';render();}});
